    uint8_t *data_cursor;
    uint32_t working_result;
    uint32_t expected_status_bits;
    uint32_t poll_attempt_limit;
    int operation_result;
    uint32_t next_dispatch_state;

    status_bits = *buffer;
    operation_result = 0;

